function zigzagDiagonals(grid: number[][]): number[] {
  const m = grid.length, n = grid[0].length;
  const diags: number[][] = Array.from({ length: m + n - 1 }, () => []);
  for (let i = 0; i < m; i++)
    for (let j = 0; j < n; j++) diags[i + j].push(grid[i][j]);
  const out: number[] = [];
  diags.forEach((d, k) => {
    if (k % 2 === 0) d.reverse();
    for (const v of d) out.push(v);
  });
  return out;
}

