class Solution:
    def zigzagDiagonals(self, grid: List[List[int]]) -> List[int]:
        m, n = len(grid), len(grid[0])
        diags = [[] for _ in range(m + n - 1)]
        for i in range(m):
            for j in range(n):
                diags[i + j].append(grid[i][j])
        out = []
        for k, d in enumerate(diags):
            out.extend(reversed(d) if k % 2 == 0 else d)
        return out

