function zigzagDiagonals(grid: number[][]): number[] {
  const m = grid.length, n = grid[0].length, out: number[] = [];
  for (let d = 0; d < m + n - 1; d++) {
    if (d % 2 === 0) {
      for (let i = Math.min(d, m - 1), j = d - i; i >= 0 && j < n; i--, j++) out.push(grid[i][j]);
    } else {
      for (let j = Math.min(d, n - 1), i = d - j; j >= 0 && i < m; i++, j--) out.push(grid[i][j]);
    }
  }
  return out;
}

